 "content": "def transform(grid):
    """Shift every row down by one, filling the top with the background."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    return [[bg] * w] + [list(row) for row in grid[:-1]]
